CREATE OR REPLACE FUNCTION public.admin_trigger_newsletter() RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ DECLARE req_id bigint; BEGIN SELECT net.http_post(url := 'https://ipnpugitercjsawupazz.supabase.co/functions/v1/send-newsletter', headers := jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||(SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'email_queue_service_role_key')), body := '{}'::jsonb) INTO req_id; RETURN req_id; END; $$; REVOKE ALL ON FUNCTION public.admin_trigger_newsletter() FROM PUBLIC; REVOKE ALL ON FUNCTION public.admin_trigger_newsletter() FROM anon; REVOKE ALL ON FUNCTION public.admin_trigger_newsletter() FROM authenticated;